from pathlib import Path
root=Path(__file__).resolve().parents[1];base=root/'baseline';out=root/'candidate'
src=(base/'app.mjs').read_text(encoding='utf-8')
src=src.replace("import {FastClothController as ClothController} from './fast-motion-controller.mjs';","import {LiveClothController as ClothController} from './live-cloth-controller.mjs';\nimport {ContinuousDemand}from'./continuous-demand.mjs';\nconst continuousDemand=new ContinuousDemand();")
src=src.replace("g.attributes.position.array.set(rows[i].positions);g.attributes.normal.array.set(rows[i].normals);", "g.attributes.position.array=rows[i].positions;g.attributes.normal.array=rows[i].normals;")
src=src.replace('g.setIndex(rows[i].indices);', 'g.setIndex(ArrayBuffer.isView(rows[i].indices)?new THREE.BufferAttribute(rows[i].indices,1):rows[i].indices);')
src=src.replace("it.solid?.motion(!!data?.audit?.cachedPhysicalReplay)","it.solid?.motion(!!physics?.running)")
src=src.replace("physics.running?'暂停参考解算':'参考物理解算（慢速）'","physics.running?'暂停实时物理':'开启实时物理'")
src=src.replace("'MP05-R2'","'MP05-CD-R01'")
src=src.replace("message('MP05：已验证衣形直接载入。标准动作使用持久实算缓存；外观变化不触发整段重算。自由物理仍为慢速参考模式。');", "message('MP05-CD-R01：实时求解候选。动作仅驱动原人物姿态，衣物由当前物理状态计算。');")
src=src.replace("displayLOD:'curved finite-thickness material aggregation; explicit native microscope',physicalReSolved:false,verifiedPhysicalStateReused:true", "displayLOD:'S1 source appearance retained; S3 development is independently audited',physicalReSolved:true,verifiedPhysicalStateReused:false")
src=src.replace("const t=data?.audit?.motionTime||rows[0]?.audit.seconds||0;", "const t=data?.audit?.simulationSeconds||rows[0]?.audit.seconds||0;")
src=src.replace("for(const it of items)it.solid.update(viewer.camera);originalRender();", "for(const it of items)it.solid.update(viewer.camera);const feature=items[0]?.info.settings.diameter*.001||.002;const z=Math.max(viewer.camera.near,viewer.camera.position.distanceTo(viewer.orbit.target));continuousDemand.update({dHeroMeters:0,featurePixels:viewer.renderer.domElement.height*feature/(2*z*Math.tan(viewer.camera.fov*Math.PI/360)),focus:mode==='whole'?0:1,visibilityDemand:1,normalizedResidual:physics?.frame?.audit?.normalizedResidual||0,contactRisk:physics?.frame?.audit?.contactRisk||0});originalRender();")
src=src.replace("ready,bootReadyMS,fastRuntime", "ready,bootReadyMS,continuousDemand:continuousDemand.audit(),physicsSource:'live',fastRuntime")
src=src.replace(" · 标准动作不重算 · 特写按需展开原纱线", " · 实时物理 · 特写保留原纱线")
src=src.replace("标准动作不重算", "实时物理候选")
# Do not imply that an unmeasured candidate already meets real-time speed.
src=src.replace("'载入已经实算的动作'", "'实时人体姿态'")
(out/'app.mjs').write_text(src,encoding='utf-8')
src=(base/'adaptive-solid.mjs').read_text(encoding='utf-8')
src=src.replace('function deform(){const pos=', 'function deform(){if(active&&micro){micro.deform();revision++;return;}const pos=')
src=src.replace('rim.visible=trims.group.visible=true;return;', 'rim.visible=trims.group.visible=true;deform();return;')
(out/'adaptive-solid.mjs').write_text(src,encoding='utf-8')
html=(base/'index.html').read_text(encoding='utf-8')
html=html.replace('MP05-R2 · 快速启动 / 持久动作缓存 / 分尺度材质','MP05-CD-R01 · 实时物理优化候选').replace('KAOPU · 原生材料与动作成衣 / MP04','KAOPU · 实时服装 / 连续需求候选')
html=html.replace('标准动作不会重新解算；正在载入已验证衣形。','正在准备原人物、裁片和实时求解器。')
html=html.replace('参考物理解算（慢速）','开启实时物理').replace('暂停人物动作','暂停模拟')
old='标准动作读取已验证的物理解算数据，按正常时间播放，不在点击时重新计算整段动作。数据保存在当前浏览器，换灯光、镜头、外观不会清空。K04、L04、D01 和 D04 的三种动作可用；其他物理组合未预计算时明确禁用，不偷偷开启几分钟等待。此模式是准确实算回放，不是实时自由布料求解。'
html=html.replace(old,'动作使用原人物的骨骼姿态，衣物实时求解；暂停可继续查看当前状态。')
html=html.replace('标准显示直接读取已验证衣形；自由物理工具按需载入原求解器。','物理尚未开启。')
html=html.replace('单层针织 / 原生皮革针路 / 上下装碰撞','原材料与裁片保留 / 实时上下装碰撞')
html=html.replace('MP04 · 原共同人物 × 原生材料 × 实算动作','MP05-CD-R01 · 原人物 × 原材料 × 实时服装')
html=html.replace('<script type="module" src="motion-transport.mjs"></script>', '<script type="module" src="live-ui.mjs"></script>')
(out/'index.html').write_text(html,encoding='utf-8')
src=(base/'visible-transport.mjs').read_text(encoding='utf-8')
src=src.replace('stage.appendChild(bar);','stage.insertAdjacentElement("afterend",bar);').replace('stage.appendChild(status);','bar.insertAdjacentElement("afterend",status);')
(out/'visible-transport.mjs').write_text(src,encoding='utf-8')
